'use strict';
const KEY=window.uniifyStorageKey||'uniify-workspace-v2';
const fresh=()=>({version:2,profile:{},answers:{},tasks:[],releases:[],entries:[],history:[],activity:[]});
let state=fresh(),storageOK=true;
try{const saved=window.uniifyInitialState||JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&[2,3].includes(saved.version))state={...fresh(),...saved};else if(KEY==='uniify-workspace-v2'){const old=JSON.parse(localStorage.getItem('uniify-v2-demo')||'null');if(old?.profile){state.profile=old.profile;state.answers=old.assessment||{};}const start=JSON.parse(localStorage.getItem('uniify-starting-point')||'null');if(start?.artist)state.profile={...state.profile,artist:start.artist,vision:start.note||''};}}catch{storageOK=false;}
const domains=[
['releasePlan','Release planning','I have a documented plan for my next release.','A timeline with preparation, release-day and follow-up actions.','Draft your release plan','Write a release goal, choose a realistic date, and list the preparation steps.','guide-release.html',60],
['rights','Rights & credits','I keep records of ownership and collaborators.','Know who contributed and where the agreed credits are recorded.','Document your rights and credits','List each contributor, their role, and the agreements you need to confirm.','guide-credits.html',45],
['branding','Artist identity','My artist profiles and branding are consistent.','Your name, biography, images and links tell the same story.','Review your artist identity','Compare your artist profiles. Update one outdated biography, image or link.','guide-routine.html',30],
['audience','Audience','I regularly review audience performance.','You have a repeatable way to learn what connects with listeners.','Choose an audience metric','Pick one useful audience measure. Record its source and the date, then set a review date.','guide-routine.html',20],
['budgetPlan','Money','I track music spending and income.','You know what you can spend and record what comes in and goes out.','Build your music budget','Set a realistic budget and add your next planned expense to Budget & income.','guide-release.html',30],
['goals','Career goals','I have clear, measurable career goals.','A specific outcome and a time frame you can review.','Set a measurable career goal','Choose one result to work towards this month and write down how you will measure it.','guide-routine.html',20]
];
const names={overview:'Overview',profile:'Artist profile',assessment:'Career foundations',roadmap:'Your roadmap',releases:'Releases',budget:'Budget & income',resources:'Guides & resources',settings:'Settings & data'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const money=v=>new Intl.NumberFormat('en',{style:'currency',currency:['GBP','NGN','USD','EUR'].includes(state.profile.currency)?state.profile.currency:'GBP',minimumFractionDigits:0,maximumFractionDigits:2}).format(v||0);
const date=v=>v?new Date(v+'T12:00:00').toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'}):'No date set';
const today=()=>new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0');
const btn=(text,action,icon='plus')=>`<button class="theme-btn-two" data-action="${action}">${text}<i class="fa-light fa-${icon}"></i></button>`;
const link=(text,view)=>`<a class="text-link" href="#${view}">${text}</a>`;
let toastTimer;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4500);}
function save(message){if(window.uniifyCloud){window.uniifyCloud.save(state);if(message)toast(message);return;}try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;if(message)toast(message);}catch{storageOK=false;toast('Storage is unavailable. Changes are in memory only; export your data before leaving.');}}
function log(text){state.activity.unshift({text,time:new Date().toISOString()});}
function score(){const a=Object.values(state.answers).filter(x=>['yes','partial','no'].includes(x));return {count:a.length,value:a.length?Math.round(a.reduce((n,v)=>n+(v==='yes'?100:v==='partial'?50:0),0)/a.length):null};}
function activeTasks(){return state.tasks.filter(t=>!t.archived);}
function progress(){const tasks=activeTasks();return {total:tasks.length,done:tasks.filter(t=>t.status==='Done').length};}
function setup(){return [!!state.profile.artist,!!state.history.length,!!state.tasks.length];}
function current(){const v=location.hash.slice(1);return names[v]?v:'overview';}
function header(title,desc,action=''){return `<div class="page-heading"><div><span class="eyebrow">Your career. Your direction.</span><h1>${title}</h1><p>${desc}</p></div>${action||`<span class="date-label">${new Date().toLocaleDateString('en',{weekday:'long',day:'numeric',month:'long'})}</span>`}</div>`;}
function taskRow(t){return `<div class="task-row ${t.status==='Done'?'done':''}"><input type="checkbox" aria-label="Complete ${esc(t.title)}" data-complete="${t.id}" ${t.status==='Done'?'checked':''}><button class="task-main text-start" style="background:none;border:0;color:inherit" data-task="${t.id}"><b>${esc(t.title)}</b><small>${esc(t.domain||'Personal task')}${t.due?' · '+date(t.due):''}</small></button><span class="tag">${esc(t.status)}</span><button class="icon-button" data-task="${t.id}" aria-label="Edit ${esc(t.title)}"><i class="fa-light fa-pen"></i></button></div>`;}
function empty(title,desc,action=''){return `<div class="empty"><i class="fa-light fa-sparkles"></i><h3>${title}</h3><p>${desc}</p>${action}</div>`;}
function overview(){const s=score(),p=progress(),steps=setup(),next=state.releases.length&&activeTasks().find(t=>!['Done','Deferred'].includes(t.status)&&!E.blocked(state,t));return header(state.profile.artist?`Make your next move, ${esc(state.profile.artist)}.`:'Your next chapter starts here.','A little clarity. A focused plan. Progress on your terms.')+`<div class="dashboard-grid"><div><section class="dashboard-hero"><img src="images/icons/music/service-icon1-3.svg" alt=""><div class="hero-text"><span class="eyebrow">${next?'Your next recommended action':'A career built around you'}</span><h2>${next?esc(next.title):'Big ambitions.<br>Practical next steps.'}</h2><p>${next?esc(next.reason||'A step you chose for your career plan.'):'Tell us where you want to go. We’ll help you turn the work ahead into a manageable plan.'}</p>${next?`<button class="theme-btn-two" data-task="${next.id}">Work on this <i class="fa-light fa-play"></i></button>`:`<a href="#${steps[0]?'releases':'profile'}" class="theme-btn-two">${steps[0]?'Create your release':'Set up your profile'} <i class="fa-light fa-plus"></i></a>`}</div></section><div class="stats-row"><div class="stat-box"><div class="stat-top">Foundations <i class="fa-light fa-chart-simple"></i></div><div class="stat-number">${s.value??'—'}<small>${s.value!==null?'/100':''}</small></div><p>${s.count} of 6 questions scored</p></div><div class="stat-box"><div class="stat-top">Roadmap progress <i class="fa-light fa-list-check"></i></div><div class="stat-number">${p.done}<small> / ${p.total}</small></div><p>Actions completed</p></div><div class="stat-box"><div class="stat-top">Active releases <i class="fa-light fa-compact-disc"></i></div><div class="stat-number">${state.releases.filter(r=>r.status!=='Archived').length}</div><p>Your projects in motion</p></div></div><section class="panel"><div class="panel-head"><h2>Your focus list</h2>${link('View roadmap','roadmap')}</div>${activeTasks().length?activeTasks().slice(0,4).map(taskRow).join(''):empty('Start with one useful action.','Create a release to build its roadmap. You can also add general career tasks.',btn('Add a task','add-task'))}</section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Recent progress</h2>${link('Review foundations','assessment')}</div>${state.activity.length?state.activity.slice(0,4).map(a=>`<div class="task-row"><i class="fa-light fa-check" style="color:var(--theme-color3)"></i><div class="task-main"><b>${esc(a.text)}</b><small>${new Date(a.time).toLocaleDateString('en',{day:'numeric',month:'short'})}</small></div></div>`).join(''):'<p class="small-copy muted">Your completed actions and plan updates will appear here.</p>'}</section></div><div><section class="service-block"><div class="inner-block"><div class="panel-head"><h2>Make it yours</h2><span class="tag">${steps.filter(Boolean).length}/3 complete</span></div><p class="small-copy">A few foundations for a more useful workspace.</p><div class="track"><span style="width:${steps.filter(Boolean).length/3*100}%"></span></div><div class="setup-list">${[['Your artist profile','profile'],['Your career foundations','assessment'],['Your first roadmap','roadmap']].map(([label,v],i)=>`<a href="#${v}" class="setup-item ${steps[i]?'done':''}"><span class="step-mark">${steps[i]?'<i class="fa-light fa-check"></i>':i+1}</span>${label}<span><i class="fa-light fa-chevron-right"></i></span></a>`).join('')}</div><p class="small-copy muted">${state.profile.goal?'Your focus: '+esc(state.profile.goal):'Choose a goal that feels right for you.'}</p></div></section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Your foundations</h2>${link('Review','assessment')}</div>${domains.map(([id,name])=>{const value={yes:100,partial:50,no:0}[state.answers[id]];return `<div class="foundation-item"><span>${name}</span><div class="track"><span style="width:${value||0}%"></span></div><b>${value===undefined?'—':value+'%'}</b></div>`}).join('')}<p class="small-copy muted">Self-reported practices, not a measure of talent. Missing answers are not failures.</p></section><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>A little guidance</h2>${link('All guides','resources')}</div>${resources.slice(0,2).map(r=>`<a class="resource-mini" href="${r.url}"><img src="${r.img}" alt=""><div><b>${r.title}</b><small>${r.label}</small></div></a>`).join('')}</section></div></div>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options,value,required=false){return `<label class="field"><span>${label}</span><select name="${name}" ${required?'required':''}><option value="">Choose ${label.toLowerCase()}</option>${options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;}
function profile(){const p=state.profile;return header('Your story. Your direction.','Help your workspace reflect the artist you are and the career you want.')+`<div class="dashboard-grid"><form class="panel" id="profile-form"><div class="panel-head"><h2>Artist essentials</h2><span class="tag">Editable anytime</span></div><div class="fields">${field('Artist name','artist',p.artist,'text','required maxlength="100"')}${select('Primary role','role',['Recording artist','Producer','Songwriter','DJ','Instrumentalist','Artist and producer','Other'],p.role,true)}${select('Career stage','stage',['Just starting','Released music, building an audience','Growing my career','Established independent artist'],p.stage,true)}${select('Primary goal','goal',['Release my first music','Grow my audience','Earn more from music','Improve career management','Find collaborators and opportunities'],p.goal,true)}${select('Biggest challenge','challenge',['Knowing what to do next','Budget and resources','Marketing and audience growth','Managing releases and tasks','Industry connections'],p.challenge)}${select('Hours each week','hours',['1–3 hours','4–7 hours','8–15 hours','16+ hours'],p.hours)}${field('Monthly music budget','budget',p.budget,'number','min="0" max="100000000" step="0.01" placeholder="Optional — blank means unknown"')}${select('Currency','currency',['GBP','NGN','USD','EUR'],p.currency||'GBP',true)}${field('Released tracks','tracks',p.tracks,'number','min="0" max="100000" step="1"')}<label class="field full"><span>What would success look like in 12 months?</span><textarea name="vision" maxlength="1500" placeholder="Make it personal. What would you like to achieve?">${esc(p.vision)}</textarea></label></div><div class="form-actions"><button class="theme-btn-two" type="submit">Save and continue <i class="fa-light fa-check"></i></button><small>Saved only in this browser.</small></div></form><div><section class="dashboard-hero"><img src="images/icons/music/service-icon1-2.svg" alt=""><div class="hero-text"><span class="eyebrow">Built around your reality</span><h2>Your pace.<br>Your possibilities.</h2><p>Your time and budget help you choose manageable actions. A budget of zero is a valid starting point.</p></div></section><div class="panel" style="margin-top:22px"><h2>Start where you are.</h2><p class="small-copy muted">Your stage is self-reported. You can change your goals and circumstances whenever they change.</p><p class="small-copy muted">Use sample information in this demo. No account or cloud storage is connected.</p></div></div></div>`;}
function assessment(){const s=score();return header('Build stronger foundations.','Six practices behind a more intentional career. Answer for where you are today.')+`<div class="dashboard-grid"><form class="panel" id="assessment-form"><div class="panel-head"><h2>Your foundations check</h2><span class="tag">6 questions</span></div>${domains.map(([id,name,q,desc])=>`<div class="question"><div><h3>${q}</h3><p>${desc}</p></div><label class="field"><span class="visually-hidden">${name}</span><select name="${id}"><option value="">Not answered</option>${[['yes','Yes'],['partial','Partly / working on it'],['no','Not yet'],['na','Not applicable']].map(([v,l])=>`<option value="${v}" ${state.answers[id]===v?'selected':''}>${l}</option>`).join('')}</select></label></div>`).join('')}<div class="form-actions"><button class="theme-btn-two" type="submit">Save and review roadmap <i class="fa-light fa-check"></i></button></div></form><div><section class="panel"><span class="eyebrow">Foundations readiness</span><div class="progress-big">${s.value===null?'Not assessed':s.value+'<small style="font-size:20px"> / 100</small>'}</div><div class="track"><span style="width:${s.value||0}%"></span></div><p class="small-copy muted" style="margin-top:20px">Based on ${s.count} of 6 questions. Yes counts as 100%, Partly as 50%, and Not yet as 0%. Unanswered and not-applicable questions are excluded.</p><p class="small-copy muted">This reflects your reported practices. It does not predict success or measure the quality of your music.</p></section><section class="panel" style="margin-top:22px"><h2>Past check-ins</h2>${state.history.length?state.history.slice(-4).reverse().map(h=>`<div class="task-row"><div class="task-main"><b>${h.score===null?'Not assessed':h.score+'/100'}</b><small>${new Date(h.time).toLocaleDateString()} · ${h.count} answers scored</small></div></div>`).join(''):'<p class="small-copy muted">Your saved assessments will appear here as your foundations evolve.</p>'}</section></div></div>`;}
let taskFilter='All',query='';
function roadmap(){const p=progress();return header('A plan you can move forward.','Keep your next steps practical. Open a task for guidance, notes, and dates.',btn('Add task','add-task'))+`<p class="welcome-note">${p.done} of ${p.total} active actions completed · Completing a task does not automatically change your foundations score.</p><div class="toolbar"><div class="filters">${['All','To do','In progress','Done','Deferred'].map(v=>`<button class="filter ${taskFilter===v?'active':''}" data-filter="${v}">${v}</button>`).join('')}</div><input class="search-input" aria-label="Search tasks" placeholder="Search your tasks…" value="${esc(query)}" id="task-search"></div><section class="panel"><div id="task-results">${taskResults()}</div></section><div class="form-actions">${btn('Review suggested updates','refresh-plan','arrows-rotate')}<small>Completed and personal tasks are preserved when you update your plan.</small></div>`;}
function taskResults(){const tasks=activeTasks().filter(t=>(taskFilter==='All'||t.status===taskFilter)&&t.title.toLowerCase().includes(query.toLowerCase()));return tasks.length?tasks.map(taskRow).join(''):empty('No tasks here yet.',taskFilter==='All'?'Take your foundations check or create a task to start your plan.':'Try another filter or add a task.',`<a href="#assessment" class="text-link">Check your foundations</a>`);}
function proposed(){let tasks=domains.filter(([id])=>['no','partial'].includes(state.answers[id])).map(([id,domain,q,desc,title,steps,url,minutes])=>({id:'foundation-'+id,title,domain,steps,url,minutes,reason:`Suggested because you marked ${domain.toLowerCase()} as ${state.answers[id]==='no'?'not yet':'partly in place'}.`,status:'To do',due:'',notes:'',generated:true,archived:false}));if(!tasks.length)tasks=[{id:'foundation-review',title:'Choose one measurable next step',domain:'Career goals',steps:'Review your current goal and choose one specific action you can complete this week.',reason:score().count?'Keep your foundations moving with a goal review.':'A general starting point until you complete your assessment.',status:'To do',due:'',notes:'',generated:true,archived:false,minutes:20}];if(state.profile.goal==='Find collaborators and opportunities')tasks.push({id:'foundation-network',title:'Prepare your collaborator introduction',domain:'Connections',steps:'Write a short introduction with your role, current project and the kind of collaboration you are looking for.',reason:'You chose finding collaborators as your primary goal.',status:'To do',generated:true,archived:false,minutes:30});return tasks;}
function refreshDialog(){const proposedTasks=proposed();openDialog('Review your roadmap',`<p>These actions follow your current foundations and goal. Each starts with work you can do without paying for a service.</p><div class="check-list">${proposedTasks.map(t=>`<label><i class="fa-light fa-check"></i>${esc(t.title)}</label>`).join('')}</div><p>${state.profile.hours?'With '+esc(state.profile.hours)+' available each week, start with one action at a time.':''} Existing task notes and completion are preserved. Old suggestions move out of the active plan; completed work stays visible.</p><div class="form-actions">${btn('Apply roadmap','apply-plan','check')}</div>`);}
function applyPlan(){const suggestions=proposed(),ids=suggestions.map(t=>t.id);state.tasks=state.tasks.map(t=>({...t,archived:t.generated&&!ids.includes(t.id)&&t.status!=='Done'}));for(const t of suggestions){const old=state.tasks.find(x=>x.id===t.id);if(old){old.archived=false;old.reason=t.reason;}else state.tasks.push(t);}log('Updated your career roadmap');save('Roadmap updated. Your previous work is preserved.');closeDialog();location.hash='roadmap';render();}
function releases(){return header('Make your next release intentional.','Give each project a date, a budget, and a clear set of milestones.',btn('New release','add-release'))+(state.releases.length?`<div class="release-grid">${state.releases.map(r=>{const done=(r.milestones||[]).filter(m=>m.done).length;return `<article class="release-card"><div class="release-art"><img src="images/icons/music/service-icon1-2.svg" alt=""><span class="tag">${esc(r.type)}</span></div><div class="release-body"><h2>${esc(r.title)}</h2><p>${date(r.date)} · ${esc(r.status)}</p><div class="track"><span style="width:${done/4*100}%"></span></div><p style="margin-top:10px">${done} of 4 milestones complete · Budget ${money(r.budget)}</p><button class="theme-btn-two" data-release="${r.id}">Manage release <i class="fa-light fa-pen"></i></button></div></article>`}).join('')}</div>`:`<section class="panel">${empty('Your music deserves a plan.','Create a release project to track preparation, delivery, promotion and review.',btn('Create your first release','add-release'))}</section>`);}
function budget(){const expenses=state.entries.filter(e=>e.type==='Expense').reduce((a,e)=>a+Number(e.amount),0),income=state.entries.filter(e=>e.type==='Income').reduce((a,e)=>a+Number(e.amount),0);return header('Make every music expense intentional.','Manual records for this workspace. No bank or royalty connection.',btn('Add entry','add-entry'))+`<div class="stats-row"><div class="stat-box"><div class="stat-top">Monthly capacity</div><div class="stat-number">${state.profile.budget===''||state.profile.budget==null?'—':money(state.profile.budget)}</div><p>Set in your artist profile</p></div><div class="stat-box"><div class="stat-top">Recorded income</div><div class="stat-number">${money(income)}</div><p>All entries</p></div><div class="stat-box"><div class="stat-top">Recorded expenses</div><div class="stat-number">${money(expenses)}</div><p>All entries</p></div></div><section class="panel"><div class="panel-head"><h2>Your ledger</h2><span class="tag">${esc(state.profile.currency||'GBP')}</span></div>${state.entries.length?`<div class="table-wrap"><table><thead><tr><th>Description</th><th>Type</th><th>Date</th><th>Amount</th><th>Action</th></tr></thead><tbody>${state.entries.map(e=>`<tr><td>${esc(e.description)}</td><td><span class="tag">${esc(e.type)}</span></td><td>${date(e.date)}</td><td>${money(e.amount)}</td><td><button class="icon-button" data-entry="${e.id}" aria-label="Edit ${esc(e.description)}"><i class="fa-light fa-pen"></i></button></td></tr>`).join('')}</tbody></table></div>`:empty('Give your budget a clear picture.','Add an expense or income entry. Every amount uses the currency selected in your profile.')}<p class="small-copy muted">Recorded balance: ${money(income-expenses)}. This is not your bank balance. Monthly capacity and all-time records cover different periods.</p></section>`;}
const resources=[{title:'Plan your next release',label:'Release planning · Practical checklist',url:'guide-release.html',img:'images/artists/studio.jpg'},{title:'Keep your credits together',label:'Rights & credits · Get organised',url:'guide-credits.html',img:'images/artists/mixing.jpg'},{title:'Build a weekly music routine',label:'Career habits · Make space',url:'guide-routine.html',img:'images/artists/guitar.jpg'}];
function guides(){return header('Good guidance. Useful next steps.','Practical starting points for the work around your music.')+`<div class="resource-grid">${resources.map(r=>`<article class="project-block"><div class="inner-block"><div class="image"><a href="${r.url}"><img src="${r.img}" alt="Creative imagery from the supplied template"></a></div><div class="content"><div class="post-meta"><span>${r.label}</span></div><h2 class="title"><a href="${r.url}">${r.title}</a></h2><a class="text-link" href="${r.url}">Read guide</a></div></div></article>`).join('')}</div><section class="panel" style="margin-top:25px"><span class="eyebrow">Looking ahead</span><h2 style="margin-top:15px">People and opportunities.</h2><p class="muted">Professional discovery and curated opportunities are planned for a future release. For now, build the profile and foundations that help you prepare.</p>${link('Review your artist profile','profile')}</section>`;}
function settings(){return header('Your workspace. Your control.','Manage the information saved on this device.')+`<div class="settings-stack"><section class="panel"><h2>About this preview</h2><p class="muted">This is an interactive local demo. It does not create a secure account, send email, connect music services, or sync across devices. Avoid entering sensitive information.</p><p class="small-copy muted">${storageOK?'Browser storage is available. Changes are saved automatically when you submit a form or update a task.':'Browser storage is unavailable. Export your data to retain this session.'}</p></section><section class="panel"><h2>Take your work with you</h2><p class="muted">Export your profile, assessments, linked release tasks, dependencies, dated transitions, scheduling revisions, career activities, audience observations and financial records as JSON.</p>${btn('Export workspace','export','download')}</section><section class="panel"><h2>Start fresh</h2><p class="muted">Clear this demo’s workspace on this device. Export anything you want to keep first.</p>${btn('Reset local workspace','reset','trash')}</section><section class="panel"><h2>Account access</h2><p class="muted">The sign-in and registration screens are design previews. Production authentication is not connected.</p><a href="signin.html" class="text-link">View sign-in screen</a></section></div>`;}
function render(){const v=current();document.querySelector('#view').innerHTML=({overview,profile,assessment,roadmap,releases,budget,resources:guides,settings,career:careerProgress}[v])();document.querySelector('#breadcrumb').textContent=names[v];document.title=names[v]+' | Uniify for Artists';document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===v);if(a.dataset.view===v)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const name=state.profile.artist||'Your artist workspace';document.querySelector('.top-avatar').textContent=(state.profile.artist||'U')[0].toUpperCase();document.querySelector('#view').classList.remove('view-enter');requestAnimationFrame(()=>document.querySelector('#view').classList.add('view-enter'));document.body.classList.remove('nav-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');}
const dialog=document.querySelector('#editor');let returnFocus=null;
function openDialog(title,html){returnFocus=document.activeElement;document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-content').innerHTML=html;dialog.showModal();}
function closeDialog(){dialog.close();returnFocus?.focus?.();}
document.querySelector('#close-dialog').onclick=closeDialog;
function taskDialog(id){const t=state.tasks.find(t=>t.id===id)||{title:'',status:'To do',due:'',notes:''};openDialog(id?'Your next step':'Add a task',`<form id="task-form" data-id="${id||''}"><div class="fields"><div class="full">${field('Task title','title',t.title,'text','required maxlength="150"')}</div>${select('Status','status',['To do','In progress','Done','Deferred'],t.status,true)}${field('Target date','due',t.due,'date')}<label class="field full"><span>Notes</span><textarea name="notes" maxlength="2000" placeholder="Your ideas, links, or progress…">${esc(t.notes)}</textarea></label></div>${t.steps?`<div style="margin-top:24px"><span class="eyebrow">Why this action</span><p>${esc(t.reason)}</p><span class="eyebrow">Start here · about ${t.minutes} minutes</span><p>${esc(t.steps)}</p>${t.url?`<a class="text-link" href="${t.url}">Open the related guide</a>`:''}</div>`:''}<div class="form-actions"><button class="theme-btn-two">Save task <i class="fa-light fa-check"></i></button>${id?`<button type="button" class="text-link" data-archive="${id}">Archive task</button>`:''}</div></form>`);}
function releaseDialog(id){const r=state.releases.find(r=>r.id===id)||{title:'',type:'Single',status:'Planning',date:'',budget:'',milestones:[]};openDialog(id?'Manage your release':'Plan a release',`<form id="release-form" data-id="${id||''}"><div class="fields"><div class="full">${field('Release title','title',r.title,'text','required maxlength="120"')}</div>${select('Release type','type',['Single','EP','Album'],r.type,true)}${select('Status','status',['Planning','In production','Scheduled','Released','Archived'],r.status,true)}${field('Target release date','date',r.date,'date','required')}${field('Project budget ('+(state.profile.currency||'GBP')+')','budget',r.budget,'number','min="0" step="0.01" max="100000000"')}</div><div class="check-list">${['Prepare music and credits','Confirm delivery and artwork','Plan release promotion','Review results and next steps'].map((label,i)=>`<label><input type="checkbox" name="milestone-${i}" ${r.milestones[i]?.done?'checked':''}>${label}</label>`).join('')}</div><p>Milestones stay complete when you change the date. This planner does not distribute your music.</p><div class="form-actions"><button class="theme-btn-two">Save release <i class="fa-light fa-check"></i></button></div></form>`);}
function entryDialog(id){const e=state.entries.find(e=>e.id===id)||{description:'',type:'Expense',amount:'',date:today()};openDialog(id?'Edit financial entry':'Add financial entry',`<form id="entry-form" data-id="${id||''}"><div class="fields"><div class="full">${field('Description','description',e.description,'text','required maxlength="120"')}</div>${select('Type','type',['Expense','Income'],e.type,true)}${field('Amount ('+(state.profile.currency||'GBP')+')','amount',e.amount,'number','required min="0.01" step="0.01" max="100000000"')}${field('Date','date',e.date,'date','required')}</div><div class="form-actions"><button class="theme-btn-two">Save entry <i class="fa-light fa-check"></i></button></div></form>`);}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){const action=a.dataset.action;if(action==='add-task')taskDialog();if(action==='add-release')releaseDialog();if(action==='add-entry')entryDialog();if(action==='refresh-plan')refreshDialog();if(action==='apply-plan')applyPlan();if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='uniify-workspace.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace export downloaded.');}if(action==='reset')openDialog('Reset this local workspace?',`<p>This removes this demo’s profile, tasks, releases, assessments and budget records from this browser. Export first if you want to retain them.</p><div class="form-actions">${btn('Export first','export','download')}<button class="text-link" data-action="confirm-reset">Delete local workspace</button></div>`);if(action==='confirm-reset'){state=fresh();save('Local workspace reset.');closeDialog();location.hash='overview';render();}}const t=e.target.closest('[data-task]');if(t)taskDialog(t.dataset.task);const r=e.target.closest('[data-release]');if(r)releaseDialog(r.dataset.release);const entry=e.target.closest('[data-entry]');if(entry)entryDialog(entry.dataset.entry);const filter=e.target.closest('[data-filter]');if(filter){taskFilter=filter.dataset.filter;render();}const archive=e.target.closest('[data-archive]');if(archive){const task=state.tasks.find(t=>t.id===archive.dataset.archive);task.archived=true;task.autoRetired=false;save('Task archived. Its history is retained in your export.');closeDialog();render();}});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){query=e.target.value;document.querySelector('#task-results').innerHTML=taskResults();}});
document.querySelector('#menu-toggle').onclick=()=>{const open=document.body.classList.toggle('nav-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open));};
window.addEventListener('hashchange',()=>{render();document.querySelector('#view').focus();window.scrollTo(0,0);});
